sys_script_include.script:
var SharkUniversityUtils = Class.create();
SharkUniversityUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	validateTrainingDate: function () {
		var trainingDate = this.getParameter('sysparm_date_value');
		var gd = new GlideDate();
		gd.setDisplayValue(trainingDate);
		var formattedDate = gd.getValue();

		var grEnrollment = new GlideRecord('x_1590365_shark_0_training_session');
		grEnrollment.addQuery('training_date', formattedDate);
		grEnrollment.query();

		var result = {
			isDuplicate: false,
			msgExistingDate: ''
		};

		if (grEnrollment.next()) {
			result.isDuplicate = true;
			result.msgExistingDate = 'Training already exists for that date!';
		}

		return JSON.stringify(result);
	},

	refQualTrainingSession: function () {
		var grEnrollment = new GlideRecord('x_1590365_shark_0_enrollment');
		var sessionsToHide = [];
		grEnrollment.addEncodedQuery('state!=4^training_session.training_date>javascript:gs.endOfToday()');
		grEnrollment.query();

		while (grEnrollment.next()) {
			var sys_idTrainingSessions = grEnrollment.getValue('training_session');
			var availableSeats = grEnrollment.getElement('training_session.max_seats').toString();
			var openedByMe = grEnrollment.getValue('opened_by');

			if ((availableSeats <= '0') || (availableSeats > '0' && openedByMe == gs.getUserID())) {
				sessionsToHide.push(sys_idTrainingSessions);
			}
		}

		if (sessionsToHide.length > 0) {
			return 'sys_idNOT IN' + sessionsToHide.join(',');
		}
		return '';
	},

	refQualTrainingSessionForm: function () {
		var isInstructorOfCourse = gs.getUserID();
		var sessionsToHide = [];
		var grTrainingSession = new GlideRecord('x_1590365_shark_0_training_session');
		grTrainingSession.addQuery('instructor', isInstructorOfCourse);
		grTrainingSession.query();

		while (grTrainingSession.next()) {	
			var sys_idTrainingSessions = grTrainingSession.getValue('sys_id');		
			if (grTrainingSession) {
				sessionsToHide.push(sys_idTrainingSessions);
			}
		}

		if (sessionsToHide.length > 0) {
			return 'sys_idNOT IN' + sessionsToHide.join(',');
		}
		return '';
	},

	type: 'SharkUniversityUtils'
});
